//! Numerical oracle transport only, generated by the unchanged original writer.
const std = @import("std");
const Original = @import("../../../frontends/riscv/recursion/air/framework_interaction.zig");
fn word(f: std.fs.File, w: u32) !void {
    var b: [4]u8 = undefined;
    std.mem.writeInt(u32, &b, w, .little);
    try f.writeAll(&b);
}
pub fn main() !void {
    const a = std.heap.page_allocator;
    const args = try std.process.argsAlloc(a);
    defer std.process.argsFree(a, args);
    if (args.len != 2) return error.ExpectedOutput;
    const f = try std.fs.cwd().createFile(args[1], .{});
    defer f.close();
    try f.writeAll("ROWM1\x00\x00\x00");
    try word(f, 17);
    for (1..18) |log| {
        const n = @as(usize, 1) << @intCast(log);
        try word(f, @intCast(n));
        for (0..n) |row| try word(f, @intCast(Original.committedRow(row, @intCast(log))));
    }
}
